def _security() -> None:
    for table in TABLES:
        op.execute(f"""
            ALTER TABLE {table} ENABLE ROW LEVEL SECURITY;
            CREATE POLICY tenant_isolation ON {table}
              USING (organisation_id = app_current_org())
              WITH CHECK (organisation_id = app_current_org());
        """)
    # Conversations are private to their author, even within the organisation.
    op.execute("""
        CREATE POLICY conversation_owner ON assistant_conversations AS RESTRICTIVE
          USING (user_id = app_current_user())
          WITH CHECK (user_id = app_current_user());
        CREATE POLICY conversation_owner ON assistant_messages AS RESTRICTIVE
          USING (conversation_id IN (SELECT id FROM assistant_conversations))
          WITH CHECK (conversation_id IN (SELECT id FROM assistant_conversations));
    """)
    op.execute(
        "REVOKE UPDATE, DELETE, TRUNCATE ON agent_execution_steps, agent_versions FROM operon_app"
    )
    op.execute("""
        CREATE FUNCTION operon_agents_due(p_now timestamptz, p_limit int)
        RETURNS TABLE (id uuid, organisation_id uuid)
        LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS
        $$ SELECT a.id, a.organisation_id FROM agents a
           WHERE a.enabled AND a.schedule <> 'off' AND a.next_run_at IS NOT NULL
             AND a.next_run_at <= p_now
           ORDER BY a.next_run_at LIMIT p_limit $$;
        REVOKE ALL ON FUNCTION operon_agents_due(timestamptz, int) FROM PUBLIC;
        GRANT EXECUTE ON FUNCTION operon_agents_due(timestamptz, int) TO operon_app;
    """)


